class UserProfile {
    private String username;
    private int age;
    private boolean active;

    public UserProfile(String username, int age) {
        this.username = username;
        this.age = age;
        this.active = true; // Default active on creation
    }

    // Standard Getter
    public String getUsername() {
        return this.username;
    }

    // Standard Setter
    public void setUsername(String username) {
        if (username != null && !username.trim().isEmpty()) {
            this.username = username.trim();
        }
    }

    // Int Getter
    public int getAge() {
        return this.age;
    }

    // Int Setter with validation
    public void setAge(int age) {
        if (age >= 13 && age <= 120) {
            this.age = age;
        }
    }

    // Boolean Getter convention: 'is' prefix
    public boolean isActive() {
        return this.active;
    }

    // Boolean Setter
    public void setActive(boolean active) {
        this.active = active;
    }
}

public class Main {
    public static void main(String[] args) {
        UserProfile user = new UserProfile("maya_coder", 24);
        System.out.println("Username: " + user.getUsername());
        System.out.println("Age: " + user.getAge());
        System.out.println("Active Status: " + user.isActive());

        user.setAge(25);
        System.out.println("Updated Age: " + user.getAge());
    }
}

