class EmployeeName {
    private String firstName;
    private String lastName;

    public EmployeeName(String first, String last) {
        this.firstName = first;
        this.lastName = last;
    }

    public String getFirstName() { return firstName; }
    public void setFirstName(String first) { this.firstName = first; }

    public String getLastName() { return lastName; }
    public void setLastName(String last) { this.lastName = last; }

    // Virtual / Computed Getter: No separate 'fullName' variable needed!
    public String getFullName() {
        return firstName + " " + lastName;
    }
}

public class Main {
    public static void main(String[] args) {
        EmployeeName emp = new EmployeeName("Ananya", "Sharma");
        System.out.println("Full Name: " + emp.getFullName());

        emp.setLastName("Verma");
        System.out.println("Updated Full Name: " + emp.getFullName());
    }
}

