class Rectangle {
    private double width;
    private double height;

    public Rectangle(double width, double height) {
        this.width = width > 0 ? width : 1.0;
        this.height = height > 0 ? height : 1.0;
    }

    public double getWidth() { return width; }
    public void setWidth(double width) {
        if (width > 0) { this.width = width; }
    }

    public double getHeight() { return height; }
    public void setHeight(double height) {
        if (height > 0) { this.height = height; }
    }

    public double getArea() {
        return width * height;
    }

    public double getPerimeter() {
        return 2 * (width + height);
    }
}

public class Main {
    public static void main(String[] args) {
        Rectangle r = new Rectangle(4.0, 5.0);
        r.setWidth(-2.0); // Rejected
        r.setHeight(6.0);  // Accepted (4.0 x 6.0)
        System.out.println("Area: " + r.getArea() + ", Perimeter: " + r.getPerimeter());
    }
}
